"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def CONVERT_SCORE(score):
    if (score >= 90):
        return 'Distinction'
    elif ((score >= 70) and (score < 90)):
        return 'Merit'
    elif ((score >= 50) and (score < 70)):
        return 'Pass'
    else:
        return 'Fail'

print(CONVERT_SCORE(95))
print(CONVERT_SCORE(75))
